from taf.config.testline import Bts2G


class Bts2GAttrs(object):
    def __init__(self, bts2g_objects):
        self.bts2g_objects = bts2g_objects

    def has_bts2g(self):
        if self.bts2g_objects is not None:
            return len(self.bts2g_objects) > 0
        return False

    def get_bts2g_objects(self):
        if self.bts2g_objects is None:
            raise AttributeError('No bts2g in testline object.')
        return [bts2g for bts2g in self.bts2g_objects if isinstance(bts2g, Bts2G)]
